import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 54 Sticky fingers","description":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 54 Sticky fingers","description":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 53 Hot snake","link":"/life/english/new-concept/book-2/unit-03/lesson-053"},"next":{"text":"第二册：实践与进步 · Lesson 55 Not a gold mine","link":"/life/english/new-concept/book-2/unit-03/lesson-055"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 53 Hot snake","link":"/life/english/new-concept/book-2/unit-03/lesson-053"},"next":{"text":"第二册：实践与进步 · Lesson 55 Not a gold mine","link":"/life/english/new-concept/book-2/unit-03/lesson-055"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-054.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-054.md"}'),i={name:"life/english/new-concept/book-2/unit-03/lesson-054.md"};function r(s,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-54-sticky-fingers" tabindex="-1">第二册：实践与进步 · Lesson 54 Sticky fingers <a class="header-anchor" href="#第二册-实践与进步-·-lesson-54-sticky-fingers" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 54 Sticky fingers&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>做果酱时手指沾满糖浆，忙着处理一件事又弄乱另一处；练习一……就与动作顺序。本课的语言观察是：No sooner had ... than ... 可强调紧接发生，并在 no sooner 前置时倒装；普通 after 句则无需这种语序，初学可先用 as soon as。完成学习后，请描写厨房里连锁发生的两件小意外，用一个紧接关系连接词。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>sticky</td><td>/ˈstɪki/</td><td>adj.</td><td>黏的</td><td>sticky fingers</td></tr><tr><td>finger</td><td>/ˈfɪŋɡə/</td><td>n.</td><td>手指</td><td>a sore finger</td></tr><tr><td>jam</td><td>/dʒæm/</td><td>n.</td><td>果酱；堵塞</td><td>a jar of jam</td></tr><tr><td>wipe</td><td>/waɪp/</td><td>v.</td><td>擦拭</td><td>wipe a table</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>wipe something off — 擦去某物</li><li>be covered in — 沾满、覆盖着某物</li></ul><h2 id="语法讲解-时间、原因与让步从句" tabindex="-1">语法讲解：时间、原因与让步从句 <a class="header-anchor" href="#语法讲解-时间、原因与让步从句" aria-label="Permalink to &quot;语法讲解：时间、原因与让步从句&quot;">​</a></h2><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：No sooner had ... than ... 可强调紧接发生，并在 no sooner 前置时倒装；普通 after 句则无需这种语序，初学可先用 as soon as。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>As soon as I opened the jar, jam ran over my fingers.</p></blockquote><p>我一打开罐子，果酱就流到了手指上。</p><p>As soon as 引出开罐动作，ran 为 run 的过去式；over my fingers 描述流过的表面。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>run 的过去式是 ran，过去分词才是 run；不能在简单过去叙事中写 jam run。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 opened the jar 与 ran over，注意 ran 的短元音，不读成 run。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>As soon as I opened the jar, jam ran over my fingers. I reached for a cloth with my clean hand. Unfortunately, the cloth knocked over a cup.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描写厨房里连锁发生的两件小意外，用一个紧接关系连接词。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：As soon as 引出开罐动作，ran 为 run 的过去式；over my fingers 描述流过的表面。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：run 的过去式是 ran，过去分词才是 run；不能在简单过去叙事中写 jam run。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 run 的过去式：Jam ___ over my fingers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> ran</p><p><strong>解析：</strong> 具体过去动作使用 ran。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>后来是什么碰倒了杯子？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The cloth.</p><p><strong>解析：</strong> 示范主语明确为 cloth，不是 jar。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“我擦掉了果酱”写成含 wipe off 的句子。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I wiped the jam off.</p><p><strong>解析：</strong> 过去叙事用 wiped，可分动词允许名词宾语在中间。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：时间、原因与让步从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-053">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-055">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",r]]);export{u as __pageData,f as default};
